class Solution:
    def deserialize(self,s: str) -> NestedInteger:
        stack=[]
        root=None
        i=0
        while i<len(s):
            c=s[i]
            if c=="[":
                node=NestedInteger()
                if stack: stack[-1].add(node)
                else: root=node
                stack.append(node)
                i+=1
            elif c=="]":
                stack.pop()
                i+=1
            elif c==",": i+=1
            else:
                end=i+(1 if c=="-" else 0)
                while end<len(s) and "0"<=s[end]<= "9": end+=1
                node=NestedInteger(int(s[i:end]))
                if stack: stack[-1].add(node)
                else: root=node
                i=end
        return root

class BSTIterator:
    def __init__(self, root):
        self.stack=[]; self._push(root)
    def _push(self,node):
        while node: self.stack.append(node); node=node.left
    def next(self):
        node=self.stack.pop(); self._push(node.right); return node.val
    def hasNext(self): return bool(self.stack)

